/* Puffy theme: the mascot's look. Every surface is a soft bubble: liquid
   colour moving inside, a bright glint where light lands, a deeper tint
   underneath. Load this file after the component styles, then put
   data-glass-theme="puffy" on <html> or any wrapper.
   --glass-tint is the focus and highlight colour. */
[data-glass-theme="puffy"] {
  --glass-tint: #7556e8;
  --glass-fg: #2b2140;
  --glass-on-tint: #ffffff;
  --glass-radius: 999px;
  --glass-shadow: 70 48 130;
  /* The palette. Everything below is worked out from --glass-tint, so
     changing that one colour recolours the whole theme. These are the
     values for the default lilac, used by browsers that can't do the maths. */
  --pf-c1: #ff9fd6;   /* warm companion */
  --pf-c2: #8fe9df;   /* cool companion */
  --pf-c3: #8fb4ff;   /* near neighbour */
  --pf-base: #cdb8ff; /* the tint, made pastel */
  --pf-soft: #b9a4f5; /* fills: slider, dots */
  --pf-wash: #f4eeff; /* paper with a hint of the tint */
  --pf-deep: #7856e2; /* the shade inside a bubble */
  --pf-ink: #4a3596;  /* text on a wash */
  /* Deeper versions for filled buttons, so white text reads on them */
  --pf-d1: #c45ac8;
  --pf-d2: #5a72e8;
  --pf-d3: #7a54e0;
  --pf-dbase: #7656e0;
}
@supports (color: oklch(from red l c h)) {
  [data-glass-theme="puffy"] {
    --pf-c1: oklch(from var(--glass-tint) 0.82 calc(c * 0.75) calc(h + 65));
    --pf-c2: oklch(from var(--glass-tint) 0.88 calc(c * 0.55) calc(h - 120));
    --pf-c3: oklch(from var(--glass-tint) 0.78 calc(c * 0.7) calc(h - 35));
    --pf-base: oklch(from var(--glass-tint) 0.82 calc(c * 0.6) h);
    --pf-soft: oklch(from var(--glass-tint) 0.74 calc(c * 0.7) h);
    --pf-wash: oklch(from var(--glass-tint) 0.965 calc(c * 0.12) h);
    --pf-deep: oklch(from var(--glass-tint) 0.55 c h);
    --pf-ink: oklch(from var(--glass-tint) 0.38 calc(c * 0.8) h);
    --pf-d1: oklch(from var(--glass-tint) 0.64 calc(c * 0.95) calc(h + 38));
    --pf-d2: oklch(from var(--glass-tint) 0.62 calc(c * 0.9) calc(h - 48));
    --pf-d3: oklch(from var(--glass-tint) 0.58 c calc(h + 8));
    --pf-dbase: oklch(from var(--glass-tint) 0.55 calc(c * 0.95) h);
  }
}
[data-glass-theme="puffy"] {
  --pf-holo: linear-gradient(115deg,
    color-mix(in srgb, var(--pf-c1) 55%, #fff) 0%,
    color-mix(in srgb, var(--pf-base) 75%, #fff) 22%,
    color-mix(in srgb, var(--pf-c3) 60%, #fff) 44%,
    color-mix(in srgb, var(--pf-c2) 70%, #fff) 62%,
    color-mix(in srgb, var(--pf-c1) 40%, #fff) 80%,
    color-mix(in srgb, var(--pf-base) 75%, #fff) 100%);
  --pf-glow: color-mix(in srgb, var(--glass-tint) 50%, transparent);
  /* Liquid: a glint, a sheen, then three blobs of colour that swim */
  --pf-liquid:
    radial-gradient(12% 24% at 14% 26%, rgb(255 255 255 / 0.7), transparent 72%),
    radial-gradient(70% 70% at 30% -14%, rgb(255 255 255 / 0.32), transparent 62%),
    radial-gradient(closest-side, var(--pf-d1), transparent),
    radial-gradient(closest-side, var(--pf-d2), transparent),
    radial-gradient(closest-side, var(--pf-d3), transparent),
    var(--pf-dbase);
  /* Clear bubble: mostly see-through, with colour pooling at the bottom */
  --pf-clear:
    radial-gradient(14% 26% at 14% 24%, rgb(255 255 255 / 0.95), transparent 72%),
    radial-gradient(70% 90% at 78% 125%, color-mix(in srgb, var(--pf-c2) 55%, transparent), transparent 62%),
    radial-gradient(70% 90% at 18% 125%, color-mix(in srgb, var(--pf-c1) 45%, transparent), transparent 62%),
    linear-gradient(180deg, rgb(255 255 255 / 0.5), color-mix(in srgb, var(--pf-wash) 22%, transparent));
  /* Solid bubble: the same shape, nothing shows through */
  --pf-solid:
    radial-gradient(14% 26% at 14% 24%, rgb(255 255 255 / 0.95), transparent 72%),
    radial-gradient(70% 90% at 78% 125%, color-mix(in srgb, var(--pf-c2) 35%, #fff), transparent 62%),
    radial-gradient(70% 90% at 18% 125%, color-mix(in srgb, var(--pf-c1) 25%, #fff), transparent 62%),
    linear-gradient(180deg, #ffffff, var(--pf-wash));
  /* Liquid you can see through */
  --pf-liquid-glass:
    radial-gradient(12% 24% at 14% 26%, rgb(255 255 255 / 0.7), transparent 72%),
    radial-gradient(70% 70% at 30% -14%, rgb(255 255 255 / 0.25), transparent 62%),
    radial-gradient(closest-side, color-mix(in srgb, var(--pf-d1) 78%, transparent), transparent),
    radial-gradient(closest-side, color-mix(in srgb, var(--pf-d2) 78%, transparent), transparent),
    radial-gradient(closest-side, color-mix(in srgb, var(--pf-d3) 78%, transparent), transparent),
    color-mix(in srgb, var(--pf-dbase) 72%, transparent);
  --pf-gloss: inset 0 0 0 1px rgb(255 255 255 / 0.8), inset 0 9px 10px -5px #fff, inset 0 -13px 16px -7px color-mix(in srgb, var(--pf-deep) 50%, transparent);
  --pf-skin:
    inset 0 0 0 1px rgb(255 255 255 / 0.75),
    inset 0 5px 8px -4px rgb(255 255 255 / 0.95),
    inset 0 -9px 13px -7px color-mix(in srgb, var(--pf-deep) 40%, transparent);
}
@keyframes pf-liquid {
  0%, 100% { background-position: 0 0, 0 0, 0% 50%, 100% 30%, 50% 100%; }
  33% { background-position: 0 0, 0 0, 65% 0%, 25% 100%, 100% 15%; }
  66% { background-position: 0 0, 0 0, 100% 85%, 0% 35%, 8% 0%; }
}
@keyframes pf-drift-one { to { background-position: 100% 0; } }
@keyframes pf-blink { 0%, 42%, 58%, 100% { transform: scaleY(1); } 50% { transform: scaleY(0.15); } }
/* A soft wobble when the cursor arrives, like touching a bubble */
@keyframes pf-jelly {
  0% { scale: 1; }
  30% { scale: 1.045 0.95; }
  55% { scale: 0.98 1.03; }
  78% { scale: 1.012 0.99; }
  100% { scale: 1; }
}

/* ---------- Button ---------- */
[data-glass-theme="puffy"] .gb[data-variant][data-effect] {
  --gb-fg: var(--glass-fg);
  --gb-fill: var(--pf-solid);
  --gb-backdrop: none;
  --gb-inset: var(--pf-skin);
  --gb-ring: rgb(var(--glass-shadow) / 0.07);
  --gb-drop: color-mix(in srgb, var(--glass-tint) 45%, transparent);
  --gb-lift: 9px;
  --gb-light: 0.4;
}
[data-glass-theme="puffy"] .gb[data-variant][data-effect]:hover:not(:disabled) { animation: pf-jelly 0.55s cubic-bezier(0.3, 0.7, 0.3, 1); }
/* Glass and bubble: see-through, blurring what is behind */
[data-glass-theme="puffy"] .gb[data-variant][data-effect="glass"],
[data-glass-theme="puffy"] .gb[data-variant][data-effect="bubble"] {
  --gb-fill: var(--pf-clear);
  --gb-backdrop: blur(12px) saturate(1.9) brightness(1.06);
}
[data-glass-theme="puffy"] .gb[data-variant][data-effect="bubble"] { --gb-inset: var(--pf-gloss); --gb-lift: 13px; }
/* The rim carries the mascot's colours */
[data-glass-theme="puffy"] .gb[data-variant]::after,
[data-glass-theme="puffy"] .gf[data-effect]::after,
[data-glass-theme="puffy"] .gc[data-effect]::after {
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: var(--pf-holo);
}
/* Primary: liquid colour inside the bubble */
[data-glass-theme="puffy"] .gb[data-variant="primary"][data-effect] {
  --gb-fg: #fff;
  text-shadow: 0 1px 2px color-mix(in srgb, var(--pf-deep) 60%, transparent);
  --gb-inset:
    inset 0 0 0 1px rgb(255 255 255 / 0.6),
    inset 0 5px 8px -4px rgb(255 255 255 / 0.9),
    inset 0 -10px 14px -6px color-mix(in srgb, var(--pf-deep) 60%, transparent);
  --gb-ring: color-mix(in srgb, var(--pf-deep) 30%, transparent);
  --gb-drop: color-mix(in srgb, var(--glass-tint) 70%, transparent);
  --gb-lift: 11px;
  --gb-light: 0.3;
  background: var(--pf-liquid);
  background-repeat: no-repeat;
  background-size: 100% 100%, 100% 100%, 70% 220%, 60% 200%, 80% 240%, auto;
  background-position: 0 0, 0 0, 0% 50%, 100% 30%, 50% 100%;
  animation: pf-liquid 9s ease-in-out infinite;
}
[data-glass-theme="puffy"] .gb[data-variant="primary"][data-effect]:hover:not(:disabled) {
  animation: pf-liquid 9s ease-in-out infinite, pf-jelly 0.55s cubic-bezier(0.3, 0.7, 0.3, 1);
}
[data-glass-theme="puffy"] .gb[data-variant="primary"][data-effect="glass"],
[data-glass-theme="puffy"] .gb[data-variant="primary"][data-effect="bubble"] {
  background: var(--pf-liquid-glass);
  background-repeat: no-repeat;
  background-size: 100% 100%, 100% 100%, 70% 220%, 60% 200%, 80% 240%, auto;
  background-position: 0 0, 0 0, 0% 50%, 100% 30%, 50% 100%;
  --gb-backdrop: blur(12px) saturate(1.9) brightness(1.06);
}
[data-glass-theme="puffy"] .gb[data-variant="primary"][data-effect="bubble"] {
  --gb-inset: inset 0 0 0 1px rgb(255 255 255 / 0.7), inset 0 9px 10px -5px #fff, inset 0 -14px 16px -6px color-mix(in srgb, var(--pf-deep) 70%, transparent);
}
[data-glass-theme="puffy"] .gb[data-variant="primary"]::after { background: linear-gradient(135deg, rgb(255 255 255 / 0.95), rgb(255 255 255 / 0.25) 40%, rgb(255 255 255 / 0.25) 60%, rgb(255 255 255 / 0.85)); }
[data-glass-theme="puffy"] .gb[data-variant="ghost"][data-effect] {
  --gb-fill: color-mix(in srgb, var(--glass-tint) calc(14% * var(--g-glow)), transparent);
  --gb-backdrop: none;
  --gb-inset: inset 0 0 0 0 transparent;
  --gb-ring: transparent;
  --gb-drop: transparent;
  --gb-light: 0;
}
[data-glass-theme="puffy"] .gb[data-variant="ghost"]::after { opacity: var(--g-glow); }
/* Loading: the mascot's two eyes, blinking */
[data-glass-theme="puffy"] .gb-spinner {
  width: 5px;
  height: 10px;
  margin-right: 9px;
  border: 0;
  border-radius: 3px;
  background: currentColor;
  box-shadow: 9px 0 0 currentColor;
  animation: pf-blink 1.5s ease-in-out infinite;
}

/* ---------- Fields ---------- */
[data-glass-theme="puffy"] .gf[data-effect] {
  --gf-fill: var(--pf-solid);
  --gf-backdrop: none;
  --gf-inset: var(--pf-skin);
  --gf-ring: rgb(var(--glass-shadow) / 0.06);
  padding-inline: 16px;
}
[data-glass-theme="puffy"] .gf[data-effect="glass"],
[data-glass-theme="puffy"] .gf[data-effect="bubble"] { --gf-fill: var(--pf-clear); --gf-backdrop: blur(12px) saturate(1.9) brightness(1.06); }
[data-glass-theme="puffy"] .gf[data-effect="bubble"] { --gf-inset: var(--pf-gloss); }
[data-glass-theme="puffy"] .gf[data-effect]:focus-within,
[data-glass-theme="puffy"] .gf[data-effect]:focus-visible,
[data-glass-theme="puffy"] .gf[data-effect][data-open],
[data-glass-theme="puffy"] .gk-cell.gf[data-effect][data-current] {
  --gf-ring: var(--glass-tint);
  --gf-halo: color-mix(in srgb, var(--glass-tint) 22%, transparent);
}
[data-glass-theme="puffy"] .gfield[data-invalid] .gf[data-effect] { --gf-ring: var(--glass-danger); }

/* ---------- Menus ---------- */
[data-glass-theme="puffy"] .gp[data-effect] {
  --gp-fill:
    radial-gradient(60% 50% at 90% 110%, color-mix(in srgb, var(--pf-c2) 40%, transparent), transparent 70%),
    radial-gradient(60% 50% at 0% 110%, color-mix(in srgb, var(--pf-c1) 40%, transparent), transparent 70%),
    #fff;
  border-radius: 24px;
  padding: 6px;
  box-shadow:
    inset 0 0 0 1px rgb(255 255 255 / 0.8),
    inset 0 6px 10px -5px #fff,
    0 0 0 1px rgb(var(--glass-shadow) / 0.07),
    0 20px 40px -16px var(--pf-glow);
}
[data-glass-theme="puffy"] .gp[data-effect="glass"],
[data-glass-theme="puffy"] .gp[data-effect="bubble"] {
  --gp-fill:
    radial-gradient(60% 50% at 90% 110%, color-mix(in srgb, var(--pf-c2) 40%, transparent), transparent 70%),
    radial-gradient(60% 50% at 0% 110%, color-mix(in srgb, var(--pf-c1) 40%, transparent), transparent 70%),
    rgb(255 255 255 / 0.62);
  -webkit-backdrop-filter: blur(22px) saturate(1.8);
  backdrop-filter: blur(22px) saturate(1.8);
}
[data-glass-theme="puffy"] .gp-hl {
  left: 6px;
  right: 6px;
  border-radius: 16px;
  background: var(--pf-holo);
  background-size: 200% 100%;
  opacity: 0.6;
  box-shadow: inset 0 3px 5px -3px #fff;
}

/* ---------- Card ---------- */
[data-glass-theme="puffy"] .gc[data-effect] {
  --gc-fill:
    radial-gradient(22% 14% at 12% 9%, rgb(255 255 255 / 0.95), transparent 75%),
    radial-gradient(60% 45% at 100% 105%, color-mix(in srgb, var(--pf-c2) 38%, transparent), transparent 70%),
    radial-gradient(60% 45% at 0% 105%, color-mix(in srgb, var(--pf-c1) 38%, transparent), transparent 70%),
    linear-gradient(180deg, #fff, var(--pf-wash));
  --gc-ring: transparent;
  --gc-radius: 32px;
  --gc-drop: inset 0 0 0 1px rgb(255 255 255 / 0.8), inset 0 -14px 22px -14px color-mix(in srgb, var(--pf-deep) 30%, transparent), 0 24px 46px -26px var(--pf-glow), 0 2px 6px rgb(var(--glass-shadow) / 0.06);
}
[data-glass-theme="puffy"] .gc[data-effect="glass"],
[data-glass-theme="puffy"] .gc[data-effect="bubble"] {
  --gc-fill:
    radial-gradient(22% 14% at 12% 9%, rgb(255 255 255 / 0.95), transparent 75%),
    radial-gradient(60% 45% at 100% 105%, color-mix(in srgb, var(--pf-c2) 38%, transparent), transparent 70%),
    radial-gradient(60% 45% at 0% 105%, color-mix(in srgb, var(--pf-c1) 38%, transparent), transparent 70%),
    linear-gradient(180deg, rgb(255 255 255 / 0.5), rgb(250 247 255 / 0.26));
  --gc-backdrop: blur(16px) saturate(1.8) brightness(1.05);
}
[data-glass-theme="puffy"] .gc[data-effect][data-level="2"] {
  --gc-radius: 24px;
  --gc-drop: inset 0 0 0 1px rgb(255 255 255 / 0.8), inset 0 -10px 16px -10px color-mix(in srgb, var(--pf-deep) 26%, transparent);
}
[data-glass-theme="puffy"] .gc[data-effect][data-active] {
  background:
    radial-gradient(22% 14% at 12% 12%, rgb(255 255 255 / 0.95), transparent 75%),
    radial-gradient(70% 60% at 100% 110%, color-mix(in srgb, var(--pf-c2) 50%, transparent), transparent 70%),
    radial-gradient(70% 60% at 0% 110%, color-mix(in srgb, var(--pf-c1) 42%, transparent), transparent 70%),
    linear-gradient(180deg, color-mix(in srgb, var(--pf-base) 40%, #fff), var(--pf-wash));
  box-shadow: inset 0 -14px 22px -14px color-mix(in srgb, var(--pf-deep) 40%, transparent), 0 16px 32px -18px var(--pf-glow);
}
[data-glass-theme="puffy"] .gc[data-effect][data-active]::after {
  padding: 2.5px;
  background-size: 280% 100%;
  animation: pf-drift-one 7s ease-in-out infinite alternate;
}

/* ---------- Progress ---------- */
[data-glass-theme="puffy"] .gpr-track {
  --gpr-track: color-mix(in srgb, var(--glass-tint) 14%, transparent);
  --gpr-fill: var(--pf-soft);
  --gpr-edge: rgb(255 255 255 / 0.7);
  box-shadow: inset 0 2px 3px rgb(var(--glass-shadow) / 0.12);
}
[data-glass-theme="puffy"] .gpr[data-accent] .gpr-fill {
  background: var(--pf-holo);
  background-size: 280% 100%;
  animation: pf-drift-one 5s ease-in-out infinite alternate;
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.7), inset 0 3px 3px -2px #fff, 0 0 14px var(--pf-glow);
}

/* ---------- Controls and small parts ---------- */
[data-glass-theme="puffy"] .gopt input:checked + .gck,
[data-glass-theme="puffy"] .gsw[aria-checked="true"] .gsw-track,
[data-glass-theme="puffy"] .gdot[aria-current="true"] {
  background: var(--pf-holo);
  background-size: 220% 100%;
  box-shadow: inset 0 3px 4px -2px #fff, inset 0 -4px 6px -3px color-mix(in srgb, var(--pf-deep) 50%, transparent), 0 3px 8px -2px var(--pf-glow);
}
/* Thumbs are little bubbles of their own */
[data-glass-theme="puffy"] .gsw-thumb {
  background: radial-gradient(40% 40% at 32% 30%, #fff, transparent 70%), radial-gradient(70% 70% at 70% 90%, color-mix(in srgb, var(--pf-c2) 60%, transparent), transparent 70%), var(--pf-wash);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.9), 0 3px 7px -1px color-mix(in srgb, var(--pf-deep) 45%, transparent);
}
[data-glass-theme="puffy"] .gsl-rail { --gsl-fill: var(--pf-soft); }
[data-glass-theme="puffy"] .gsl-thumb {
  background: radial-gradient(40% 40% at 32% 30%, #fff, transparent 70%), radial-gradient(70% 70% at 70% 90%, color-mix(in srgb, var(--pf-c1) 70%, transparent), transparent 70%), var(--pf-wash);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.9), 0 4px 9px -2px color-mix(in srgb, var(--pf-deep) 50%, transparent);
}
[data-glass-theme="puffy"] .gck { box-shadow: var(--pf-skin), 0 0 0 1px rgb(var(--glass-shadow) / 0.12); }
[data-glass-theme="puffy"] .gth-dots i { background: var(--pf-soft); box-shadow: inset 0 1px 1px #fff; }
[data-glass-theme="puffy"] .gdl { border-radius: 34px; box-shadow: inset 0 0 0 1px #fff, inset 0 -18px 28px -18px color-mix(in srgb, var(--pf-deep) 30%, transparent), 0 0 0 1px color-mix(in srgb, var(--pf-deep) 16%, transparent), 0 30px 60px -20px color-mix(in srgb, var(--pf-deep) 50%, transparent); }
[data-glass-theme="puffy"] .gbd[data-tone="accent"] { --gbd-c: var(--pf-ink); --gbd-bg: color-mix(in srgb, var(--pf-base) 35%, #fff); }
[data-glass-theme="puffy"] .gbn { border-radius: 22px; box-shadow: var(--pf-skin), 0 0 0 1px rgb(var(--glass-shadow) / 0.06), 0 12px 24px -14px var(--pf-glow); }
[data-glass-theme="puffy"] .gtabs-pill { box-shadow: var(--pf-skin), 0 2px 6px -1px var(--pf-glow); }

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  [data-glass-theme="puffy"] { --pf-clear: linear-gradient(180deg, #fff, var(--pf-wash)); }
}
@media (prefers-reduced-motion: reduce) {
  [data-glass-theme="puffy"] .gb[data-variant][data-effect],
  [data-glass-theme="puffy"] .gb[data-variant][data-effect]:hover:not(:disabled),
  [data-glass-theme="puffy"] .gc[data-effect][data-active]::after,
  [data-glass-theme="puffy"] .gpr[data-accent] .gpr-fill,
  [data-glass-theme="puffy"] .gb-spinner { animation: none; }
}
[data-glass-theme="puffy"] .gsw { --gsw-on: var(--pf-holo); }

/* ---------- Every other part follows the theme too ----------
   The newer families (extras, tactile, glance, kit and the AI parts) keep
   their own colour tokens. These rules route their surfaces, main buttons and
   quiet buttons through the theme. The doubled attribute lets them win over
   each family's own dark-mode rules. */
[data-glass-theme="puffy"] {
  /* deep liquid for filled buttons, so white text reads */
  --pf-main: radial-gradient(14% 30% at 16% 24%, rgb(255 255 255 / 0.55), transparent 72%), linear-gradient(115deg, var(--pf-d1), var(--pf-dbase) 48%, var(--pf-d2));
  --pf-main-lit: inset 0 0 0 1px rgb(255 255 255 / 0.35), inset 0 5px 8px -4px rgb(255 255 255 / 0.55), inset 0 -8px 12px -6px color-mix(in srgb, var(--pf-deep) 65%, transparent), 0 8px 18px -8px color-mix(in srgb, var(--glass-tint) 75%, transparent);
  --pf-card: linear-gradient(180deg, #ffffff, var(--pf-wash));
  --pf-card-lit: inset 0 0 0 1px rgb(255 255 255 / 0.8), inset 0 -10px 18px -12px color-mix(in srgb, var(--pf-deep) 30%, transparent), 0 0 0 1px rgb(var(--glass-shadow) / 0.07), 0 18px 36px -22px color-mix(in srgb, var(--glass-tint) 55%, transparent);
  --pf-quiet: linear-gradient(180deg, #ffffff, color-mix(in srgb, var(--pf-wash) 70%, #fff));
  --pf-quiet-lit: var(--pf-skin), 0 0 0 1px rgb(var(--glass-shadow) / 0.08), 0 6px 14px -8px color-mix(in srgb, var(--glass-tint) 45%, transparent);
  --pf-flat: color-mix(in srgb, var(--pf-wash) 55%, #fff);
}
:is(:is([data-glass-mode="dark"], .dark) [data-glass-theme="puffy"], :is([data-glass-mode="dark"], .dark)[data-glass-theme="puffy"]) {
  --pf-card: linear-gradient(180deg, color-mix(in srgb, var(--glass-tint) 10%, #26262c), color-mix(in srgb, var(--glass-tint) 5%, #1c1c21));
  --pf-card-lit: inset 0 1px 0 rgb(255 255 255 / 0.08), 0 0 0 1px color-mix(in srgb, var(--glass-tint) 22%, rgb(255 255 255 / 0.06)), 0 18px 36px -20px rgb(0 0 0 / 0.9), 0 0 32px -12px color-mix(in srgb, var(--glass-tint) 30%, transparent);
  --pf-quiet: linear-gradient(180deg, color-mix(in srgb, var(--glass-tint) 12%, #2c2c33), color-mix(in srgb, var(--glass-tint) 6%, #232328));
  --pf-quiet-lit: inset 0 1px 0 rgb(255 255 255 / 0.1), 0 0 0 1px color-mix(in srgb, var(--glass-tint) 25%, rgb(255 255 255 / 0.06)), 0 6px 14px -8px rgb(0 0 0 / 0.8);
  --pf-flat: color-mix(in srgb, var(--glass-tint) 8%, #1f1f24);
}
/* family tokens: surfaces take the bubble paper, main colour takes the liquid */
[data-glass-theme][data-glass-theme="puffy"] :is(.gxc-menu, .gxo-panel, .gxt, .gxa) { --gx-card: var(--pf-flat); --gx-r: 20px; }
[data-glass-theme][data-glass-theme="puffy"] :is(.goa) { --x-card: var(--pf-flat); }
